    else if(R.page==="ag")renderAgents(await (await apiFetch("/api/agents")).json());
    else if(R.page==="cd"){renderAuth(d.auth);renderThemes();renderNotifySettings();if(!CFG)loadConfig();
      renderLan(await (await apiFetch("/api/lan")).json(),d.auth)}
    else if(R.page==="nv"){const a=await (await apiFetch("/api/accounts")).json();lastAccounts=a.accounts;renderNV(a)}
    else if(R.page==="task"){const r=await apiFetch("/api/task?id="+encodeURIComponent(R.id));
      if(r.ok){renderDetail(await r.json());
        try{const f=await (await apiFetch("/api/files?id="+encodeURIComponent(R.id))).json();if(!f.error)renderProducts(R.id,f)}catch(e){}}
